import { useRef } from "react";
import type { KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

const ACCENTS: readonly { id: Accent; label: string }[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const count = ACCENTS.length;
  const checkedIndex = Math.max(0, ACCENTS.findIndex((a) => a.id === value));

  function choose(index: number) {
    buttons.current[index]?.focus();
    const id = ACCENTS[index].id;
    if (id !== value) onChange(id);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = (index + 1) % count;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = (index - 1 + count) % count;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = count - 1;
        break;
      default:
        return;
    }
    event.preventDefault();
    choose(next);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {ACCENTS.map(({ id, label }, index) => {
        const checked = index === checkedIndex;
        return (
          <button
            key={id}
            ref={(el) => {
              buttons.current[index] = el;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            className="accent-option"
            onClick={() => choose(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-swatch" aria-hidden="true" data-accent={id} />
            <span className="accent-name">{label}</span>
            <span className="accent-check" aria-hidden="true" />
          </button>
        );
      })}
    </div>
  );
}
```

```css
.accent-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  font: inherit;
}

.accent-option {
  font: inherit;
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  padding: 0.45em 0.9em 0.45em 0.6em;
  border: 1px solid var(--hair);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease;
}

.accent-option:hover {
  background: var(--myelin-wash);
}

.accent-option[aria-checked="true"] {
  border-color: var(--ink);
  background: var(--myelin-wash);
}

.accent-swatch {
  flex: none;
  width: 1em;
  height: 1em;
  border-radius: 50%;
  background: var(--myelin);
}

.accent-option[aria-checked="true"] .accent-swatch {
  box-shadow: 0 0 0 2px var(--slide), 0 0 0 3px var(--ink);
}

.accent-check {
  display: none;
  flex: none;
  width: 0.35em;
  height: 0.7em;
  margin-left: 0.2em;
  border-right: 2px solid var(--ink);
  border-bottom: 2px solid var(--ink);
  transform: rotate(45deg) translate(-0.1em, -0.1em);
}

.accent-option[aria-checked="true"] .accent-check {
  display: inline-block;
}

:root[data-motion="reduce"] .accent-option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .accent-option {
    transition: none;
  }
}
```

Note: the design tokens expose each accent's colour only as the active `--myelin` override, with no per-accent token names. So every swatch currently shows the active accent's colour. To show each accent's own colour, the design system needs named tokens such as `--accent-emerald`; then set `background` on `.accent-swatch[data-accent="emerald"]` and the others.

